unsigned long prevLed1 = 0;
unsigned long prevLed2 = 0;
const long interval1 = 500;
const long interval2 = 350;
bool state1 = false;
bool state2 = false;

void setup() {
  pinMode(13, OUTPUT);
  pinMode(12, OUTPUT);
}

void loop() {
  unsigned long teper = millis();

  if (teper - prevLed1 >= interval1) {
    prevLed1 = teper;
    state1 = !state1;
    digitalWrite(13, state1);
  }

  if (teper - prevLed2 >= interval2) {
    prevLed2 = teper;
    state2 = !state2;
    digitalWrite(12, state2);
  }
}
